template <int N>
struct Factorial {
    // Recursive computation performed at compile time
    static constexpr int value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Usage: F5 is a compile-time constant (120)
// The recursion is optimized away by the compiler (Zero Cost)
constexpr int F5 = Factorial<5>::value;
